const assetById = new Map(BUILD_ASSETS.map(asset => [asset.id, asset]));
export function getBuildAsset(id: string): BuildAsset | undefined { return assetById.get(id); }
export function getBuildAssets(category?: BuildAssetCategory): readonly BuildAsset[] {
  return category ? BUILD_ASSETS.filter(asset => asset.category === category) : BUILD_ASSETS;
}
